tool_args.issues_yaml:
- id: "R2-N1"
  summary: "Title/framing promises general answer but experiments only cover SFT ≤3B"
  category: framing
  severity: critical
  status: in_progress
  first_raised_round: 2
  last_seen_round: 6
  mentions:
    - {round: 2, reviewers: "R1,R2", note: "Table 2: vanilla 2PL MAE ≤ ContamCal on all benchmarks. Title/Abstract promise contamination-aware calibration but experiments show standard IRT suffices."}
    - {round: 3, reviewers: "R1,R2", note: "Title still 'ContamCal'. Abstract implies contamination-specific modeling."}
    - {round: 4, reviewers: "R1,R2", note: "Title 'Decomposing Contamination from Calibration' promises decomposition but core result is nothing to decompose (~0.6-0.7pp). 'Diagnostic value' pivot introduced too late (§1 ¶4). R1 and R2 both AGREE this is narrative mismatch. Suggest empirical investigation framing."}
    - {round: 5, reviewers: "R1,R2", note: "Title changed to question form ('Does LLM Benchmark Contamination Need Calibration?') but framing still inconsistent. Intro ¶1-3 heavily motivate calibration, Results show calibration unnecessary. Contributions 1-3 span empirical finding / engineering observation / exploratory analysis without unified main line. 'Why not just use raw accuracy?' paragraph in Conclusion reads as arguing against paper's own existence. Both AGREE: need full empirical investigation framing from ¶1, ContamCal as investigative instrument not product."}
    - {round: 6, reviewers: "R1,R2", note: "Title question form improved but still over-scopes. R1-N1 and R2-N2 unanimously agree: 'Does LLM Benchmark Contamination Need Calibration?' implies general answer but experiments only SFT ≤3B. Abstract second sentence scopes but title does not. Conclusion 'applies directly to settings with larger effects' is unsupported forward claim. Both AGREE title must scope or be modified."}
  action_items:
    - {round: 2, action: "Reframe paper", assigned_to: "paper_agent", status: "done"}
    - {round: 3, action: "Change title, rewrite Abstract/Contributions", assigned_to: "paper_agent", status: "done"}
    - {round: 4, action: "Reframe as empirical investigation rather than method paper", assigned_to: "paper_agent", status: "done"}
    - {round: 5, action: "Rewrite Introduction from ¶1 as question-driven empirical investigation; ContamCal as tool not contribution; consolidate Contributions to 2 items", assigned_to: "paper_agent", status: "done"}
    - {round: 6, action: "Modify title to scope claim (e.g. add 'SFT-Injected' or similar); remove Conclusion 'applies directly' unsupported claim", assigned_to: "paper_agent", status: "open"}
  resolution: ""
  resolution_round: null

- id: "R2-W6"
  summary: "SFT injection ecological validity insufficient — null finding may be SFT artifact, not general property"
  category: experiment
  severity: critical
  status: in_progress
  first_raised_round: 2
  last_seen_round: 6
  mentions:
    - {round: 2, reviewers: "R1,R2", note: "Intro motivates with pretraining but experiments only SFT."}
    - {round: 3, reviewers: "R1,R2", note: "Limitations one sentence only."}
    - {round: 4, reviewers: "R1,R2", note: "Elevated to critical. Abstract/Conclusion still say 'raw accuracy is already well-calibrated' without qualification. Pretraining contamination (arXiv 2601.04301) shows significantly larger effects. All claims must be scoped to 'under SFT injection at ≤3B scale'. Both reviewers AGREE unanimously."}
    - {round: 5, reviewers: "R1,R2", note: "Claims now scoped with 'Under SFT injection at ≤3B' in Abstract. But title still asks generic question. R2 adds: SFT vs pretraining differs in mechanism not just scale — pretraining contamination embeds into representations (θ) not just LoRA adapter. §5.5 θ asymmetry already hints at this. Both AGREE title needs scoping or Abstract first sentence must scope."}
    - {round: 6, reviewers: "R1,R2", note: "R1: LoRA SFT (α=32, r=16) is parameter-efficient lightweight fine-tuning, representation-level impact incomparable to pretraining contamination. ≤3B models baseline accuracy ~0.55-0.65 may lack memorization capacity. R2: Conclusion 'applies directly to settings with larger effects' is unsupported forward claim. Both AGREE scope limitation persists despite prior improvements."}
  action_items:
    - {round: 3, action: "Expand Limitations ecological validity discussion", assigned_to: "paper_agent", status: "done"}
    - {round: 4, action: "Scope all claims in Abstract/Intro/Conclusion to 'under SFT injection at ≤3B'", assigned_to: "paper_agent", status: "done"}
    - {round: 4, action: "Cite and discuss pretraining contamination dose-response literature as contrast", assigned_to: "paper_agent", status: "done"}
    - {round: 5, action: "Ensure Abstract first sentence explicitly scopes to SFT injection", assigned_to: "paper_agent", status: "done"}
    - {round: 6, action: "Remove/caveat Conclusion 'applies directly' claim; consider 7B+ pilot experiment to expand scope", assigned_to: "paper_agent", status: "open"}
  resolution: ""
  resolution_round: null

- id: "R3-W10"
  summary: "Additive linear γ assumption untested — oracle ablation cannot distinguish null effect from model misspecification"
  category: method
  severity: critical
  status: in_progress
  first_raised_round: 3
  last_seen_round: 6
  mentions:
    - {round: 3, reviewers: "R1", note: "Linear γ may average down to non-significant."}
    - {round: 4, reviewers: "R1,R2", note: "Elevated to critical. Oracle ablation (AUC=1.0, γ=-0.012 non-sig) has two interpretations: (a) genuine null effect (heterogeneity cancels), (b) model misspecification (linear γ cannot capture threshold/interaction effects). Paper adopts (a) without testing (b). Limitations ¶9 acknowledges threshold possibility but §5.1 oracle section ignores it. Both reviewers AGREE this is fundamental ambiguity."}
    - {round: 5, reviewers: "R1,R2", note: "§5.1 oracle paragraph now presents both interpretations. R2 partial REBUT on R1-N1: aggregate 0.6-0.7pp is model-free observation (direct d000 vs d005/d025/d100 accuracy comparison), misspecification only affects γ diagnostic claims. Both AGREE: paper must distinguish model-free findings (aggregate accuracy shift) from model-dependent findings (γ significance/direction). γ-related claims need 'under additive linear specification' caveat."}
    - {round: 6, reviewers: "R1,R2", note: "Both reviewers unanimously re-raise as critical. Oracle ablation framed as 'confirms filtering not circular' (§5.1 para 5) sidesteps the fundamental model specification question. R2 proposes concrete resolution: add threshold DGP condition to existing simulation framework (20 conditions × 10 seeds), fit linear γ, observe attenuation pattern. Low computational cost, high diagnostic value. Both AGREE this is required."}
  action_items:
    - {round: 3, action: "Discuss linearity assumption in Limitations", assigned_to: "paper_agent", status: "done"}
    - {round: 4, action: "Test item-level γ_i or γ×a_i interaction model as misspecification check", assigned_to: "main_agent", status: "done"}
    - {round: 4, action: "If not testable, explicitly scope claim as 'under linear additive specification'", assigned_to: "paper_agent", status: "done"}
    - {round: 5, action: "Add 'under the additive linear specification' caveat to γ-related claims; distinguish model-free vs model-dependent findings", assigned_to: "paper_agent", status: "done"}
    - {round: 6, action: "Run threshold DGP simulation: generate data with step-function contamination, fit linear γ, report attenuation pattern to distinguish 'no effect' from 'wrong model'", assigned_to: "main_agent", status: "open"}
  resolution: ""
  resolution_round: null

- id: "R4-N1"
  summary: "Domain-level γ significance (Social Sciences 1/8) lacks multiple comparison correction + underpowered J"
  category: method
  severity: critical
  status: in_progress
  first_raised_round: 4
  last_seen_round: 6
  mentions:
    - {round: 4, reviewers: "R1,R2", note: "8 independent domain tests, only Social Sciences significant at α=0.05. Bonferroni α=0.00625; CI upper bound -0.10 would likely include zero. BH correction also unlikely to survive 1/8 pattern. This is the sole evidence for 'diagnostic value' narrative. Both AGREE correction needed."}
    - {round: 5, reviewers: "R1,R2", note: "R1 reconfirms: Bonferroni threshold P(γ<0)≥99.375%, Social Sciences at 99.1% does not pass. R2 AGREE with nuance: (1) Bayesian posteriors don't strictly need frequentist correction per Gelman 2012, BUT independent per-domain fits without shrinkage do need correction; (2) Abstract reports P(γ<0)=99.1% without any multiplicity caveat. Both AGREE: report corrected result, or switch to hierarchical IRT for natural shrinkage."}
    - {round: 6, reviewers: "R1,R2", note: "R1-N3 elevates to critical (self-contradiction between J≥50 standard and J=13 domain analysis). R2 AGREE with nuance: 'self-contradiction' overstates but presentation weight mismatch is real. J=16 results (99.7%) cross Bonferroni but main text still uses J=13 (99.1%). Abstract presents 99.1% with high visual weight. Both AGREE: use J=16 in main text, reduce domain γ prominence in Abstract."}
  action_items:
    - {round: 4, action: "Report Bonferroni and BH corrected results for domain-level γ", assigned_to: "paper_agent", status: "done"}
    - {round: 4, action: "If non-significant after correction, reframe as 'suggestive pattern requiring higher-powered replication'", assigned_to: "paper_agent", status: "done"}
    - {round: 5, action: "Add 'uncorrected for multiplicity' when reporting P(γ<0)=99.1% in Abstract/Results; C3 demoted to observation", assigned_to: "paper_agent", status: "done"}
    - {round: 6, action: "Switch main text domain γ to J=16 results; reduce Social Sciences finding prominence in Abstract to secondary observation", assigned_to: "paper_agent", status: "open"}
  resolution: ""
  resolution_round: null

- id: "R3-N3"
  summary: "ARC PPP < 0.05 across all J configurations — IRT results unreliable"
  category: method
  severity: warning
  status: in_progress
  first_raised_round: 3
  last_seen_round: 6
  mentions:
    - {round: 3, reviewers: "R1", note: "Within-family J=13 ARC PPP=0.003 not reported."}
    - {round: 4, reviewers: "R1,R2", note: "ARC PPP < 0.05 at J=8, 13, 16 per §5.4. Table 3 still reports ARC IRT results without PPP annotation. R2 nuance: ARC ~0.7pp from raw data is valid, but IRT-derived numbers are unreliable. Both AGREE Table 3 needs PPP annotation and ARC IRT results need caveat."}
    - {round: 5, reviewers: "R1,R2", note: "Table 3 now has PPP=0.003 in caption, but ARC IRT results still in main table alongside MMLU giving visual parity. R1: move ARC IRT to Appendix or grey out. R2 AGREE: also helps solve page limit (R5-N1) by shrinking Table 3. Both AGREE 2PL+γ structural misfit for ARC (not just sample size issue) should be discussed in main text."}
    - {round: 6, reviewers: "R1,R2", note: "Improvement noted: ARC IRT moved to Appendix sec:arc_irt, Table 1 now MMLU-only. R1-W3 re-raises with nuance: §5.1 still mentions 'ARC exhibits the same pattern' which may mislead readers into treating ARC IRT results as equally reliable. R2 agrees: make explicit that ARC IRT parameters are uninterpretable due to misfit. Downgraded from critical to warning given appendix move."}
  action_items:
    - {round: 3, action: "Report ARC PPP=0.027 with caveat", assigned_to: "paper_agent", status: "done"}
    - {round: 4, action: "Add PPP annotation to ARC column in Table 3", assigned_to: "paper_agent", status: "done"}
    - {round: 4, action: "Discuss ARC misfit source (item pool heterogeneity vs model specification)", assigned_to: "paper_agent", status: "done"}
    - {round: 5, action: "Move ARC IRT results to Appendix; discuss structural misfit in main text", assigned_to: "paper_agent", status: "done"}
    - {round: 6, action: "Clarify in §5.1 that ARC IRT parameters are unreliable due to structural misfit; keep only raw accuracy for ARC in main text", assigned_to: "paper_agent", status: "open"}
  resolution: ""
  resolution_round: null

- id: "R2-W1"
  summary: "RRF multi-signal fusion — value is exposure variance, not signal quality; MAE random control missing"
  category: method
  severity: warning
  status: in_progress
  first_raised_round: 2
  last_seen_round: 6
  mentions:
    - {round: 2, reviewers: "R1,R2", note: "RRF = S1 only."}
    - {round: 3, reviewers: "R1,R2", note: "C2 wording overclaims."}
    - {round: 4, reviewers: "R1,R2", note: "Elevated to critical by R2. S2 reverses at 0.5B, S4 near-random below 1.5B. §5.2 admits RRF degrades to S1-only. No direct RRF vs S1-only ablation (τ, MAE, γ) at 1.5B/3B where S2 d≈+0.7. R1 partially rebuts absolute claim but agrees ablation is missing. Contribution 2 unsupported without this evidence."}
    - {round: 5, reviewers: "R1,R2", note: "RRF ablation now complete: S1-only causes MCMC non-convergence (MMLU R̂=1.53) due to exposure variance compression ([0.749,0.867]). This proves RRF necessary for IRT convergence. However R1 W3 insight: ablation evidence supports RRF for exposure VARIANCE, not signal QUALITY. Paper conflates these. Both AGREE: precise the contribution claim. Downgraded to warning."}
    - {round: 6, reviewers: "R1,R2", note: "R1-W5: Random 300-item subsets report τ=0.554±0.048 but no MAE comparison. If random MAE is similarly low, filtering value is limited to rank correlation. 300/14042 (2%) selection means extreme tail items only. R2 AGREE. Additionally, exclusion sensitivity analysis (§5.1) removes from random set (opposite direction to selection), not directly comparable."}
  action_items:
    - {round: 3, action: "Reword C2 in D134 reframing", assigned_to: "paper_agent", status: "done"}
    - {round: 4, action: "Provide RRF vs S1-only ablation at 1.5B and 3B (τ, MAE, γ significance)", assigned_to: "main_agent", status: "done"}
    - {round: 4, action: "If RRF ≤ S1-only, downgrade Contribution 2 to 'item filtering improves IRT' without RRF-specific claim", assigned_to: "paper_agent", status: "done"}
    - {round: 5, action: "Distinguish exposure variance contribution from signal quality; report RRF composite AUC vs S1-only AUC", assigned_to: "paper_agent", status: "done"}
    - {round: 6, action: "Report MAE for random 300-item subsets alongside τ to complete the comparison", assigned_to: "main_agent", status: "open"}
  resolution: ""
  resolution_round: null

- id: "R2-N2"
  summary: "CI coverage systematically abnormal — over-coverage and under-coverage have different root causes"
  category: method
  severity: warning
  status: in_progress
  first_raised_round: 2
  last_seen_round: 6
  mentions:
    - {round: 2, reviewers: "R1,R2", note: "Need 80%/95% coverage + root cause diagnosis."}
    - {round: 3, reviewers: "R1,R2", note: "§5.1 only reports 50%. 80%/95% completely missing."}
    - {round: 4, reviewers: "R1,R2", note: "CI coverage now reported in Limitations: MMLU 83%/89%/100%, ARC 45%/65%/90%. ARC under-coverage corroborates PPP<0.05 misfit. Both AGREE this should be in main results, not just Limitations."}
    - {round: 5, reviewers: "R1,R2", note: "CI coverage now in §5.1 main results. R1: MMLU 95% CI covers 100% = completely uninformative. R2 AGREE: over-coverage (MMLU) and under-coverage (ARC) have different root causes and should be discussed separately."}
    - {round: 6, reviewers: "R1,R2", note: "Improvement: CI coverage now in §5.1 with MMLU/ARC split. R1-W4 and R2 both agree root cause diagnosis still insufficient. MMLU over-coverage (50% CI=83%) = uninformatively wide posteriors (data-to-prior ratio too low at J=16, consistent with Appendix C prior sensitivity). ARC under-coverage (50% CI=45%) = structural misfit (PPP=0.003). Paper lumps as 'benchmark-dependent'. Both AGREE: separate diagnosis needed."}
  action_items:
    - {round: 2, action: "Report 80% and 95% CI empirical coverage", assigned_to: "main_agent", status: "done"}
    - {round: 4, action: "Move CI coverage discussion to main results section", assigned_to: "paper_agent", status: "done"}
    - {round: 5, action: "Discuss over-coverage and under-coverage root causes separately", assigned_to: "paper_agent", status: "done"}
    - {round: 6, action: "Provide explicit root-cause diagnosis: MMLU over-coverage from insufficient data-to-prior ratio; ARC under-coverage from structural misfit. Remove 'benchmark-dependent' umbrella framing.", assigned_to: "paper_agent", status: "open"}
  resolution: ""
  resolution_round: null

- id: "R2-N4"
  summary: "J values inconsistent across analyses (13/16/18/20/24/28) — J=13 domain finding vs J≥50 standard is self-contradictory"
  category: experiment
  severity: critical
  status: in_progress
  first_raised_round: 2
  last_seen_round: 6
  mentions:
    - {round: 2, reviewers: "R1,R2", note: "Paper proves its own empirical analysis is underpowered."}
    - {round: 3, reviewers: "R1,R2", note: "Contribution 4 combines simulation + empirical. Should split."}
    - {round: 4, reviewers: "R1,R2", note: "J inconsistency from experimental timeline (domain runs before 3B retraining). All γ conclusions at J=13-16 are underpowered by paper's own standard. Both AGREE needs prominent caveat and ideally unified J."}
    - {round: 5, reviewers: "R1,R2", note: "Model set table in Appendix B. But core problem: most interesting finding (domain γ) uses weakest configuration (J=13). Prior sensitivity in Appendix C uses J=16 for Social Sciences but main Table 2 still reports J=13. Both AGREE: either rerun domain analysis at J=16, or explicitly state J=13 vs J=16 consistency in main text."}
    - {round: 6, reviewers: "R1,R2", note: "R1-N3 elevates to critical. J=16 data available (Appendix Table 4) but main text §5.4 still presents J=13. 7 different J values across sections without cohesive overview. R2-W5 AGREE: readers need constant table-checking. Both AGREE: (a) use J=16 in main text; (b) add model set overview paragraph at §5 start."}
  action_items:
    - {round: 3, action: "Split Contribution 4", assigned_to: "paper_agent", status: "done"}
    - {round: 4, action: "Present J and model composition prominently in each table/figure", assigned_to: "paper_agent", status: "done"}
    - {round: 5, action: "Rerun domain-level γ at J=16 for cross-validation", assigned_to: "main_agent", status: "done"}
    - {round: 6, action: "Switch main text to J=16 domain results; add model set overview paragraph at §5 start", assigned_to: "paper_agent", status: "open"}
  resolution: ""
  resolution_round: null

- id: "R4-W1"
  summary: "RRF-filtered 300 items vs random 2000 items — item discrimination confound"
  category: experiment
  severity: warning
  status: resolved
  first_raised_round: 4
  last_seen_round: 5
  mentions:
    - {round: 4, reviewers: "R1,R2", note: "τ=0.73 (300 RRF) vs 0.46 (2000 random) may reflect higher average a_i in RRF-selected items, not contamination signal value. Need discrimination-matched random subset comparison or report average a_i of RRF vs random sets."}
    - {round: 5, reviewers: "", note: "Not independently re-raised in R5. Resolution from R4 (mean a_i comparison, Cohen's d=0.098) appears in §5.1. Resolved."}
  action_items:
    - {round: 4, action: "Report average a_i for RRF-selected vs random items; add discrimination-matched control", assigned_to: "main_agent", status: "done"}
  resolution: "Mean a_i comparison: RRF-selected mean=1.12, random mean=1.09, Cohen's d=0.098, r=-0.013. No discrimination confound. §5.1 documents this exclusion. Not re-raised in R5 or R6."
  resolution_round: 5

- id: "R1-C2"
  summary: "Cross-family analysis (J=4, single seed) — caveat adequate but MAE CI missing"
  category: experiment
  severity: warning
  status: in_progress
  first_raised_round: 1
  last_seen_round: 6
  mentions:
    - {round: 1, reviewers: "R1,R2", note: "Llama N=3."}
    - {round: 3, reviewers: "R1,R2", note: "'Validated' too strong for single-seed N=3-4."}
    - {round: 4, reviewers: "R1,R2", note: "§4.2 references 'Appendix E post-hoc power calculations' but Appendix E contains baseline tables, not power analysis. Missing content. Both strongly AGREE."}
    - {round: 5, reviewers: "R1,R2", note: "Phantom reference removed. §5.5 title still 'Cross-Family Validation'. Both AGREE: rename."}
    - {round: 6, reviewers: "R1,R2", note: "R1-W2: conclusion boundaries still unclear. R2 partial REBUT: paper has adequate 'exploratory' labeling, catastrophic collapse documentation, and scoped conclusions. R2 notes MAE CI for cross-family pool not reported. Minor residual issue."}
  action_items:
    - {round: 3, action: "Replace 'validated' with 'preliminary evidence'", assigned_to: "paper_agent", status: "done"}
    - {round: 4, action: "Write and include actual Appendix E power analysis OR remove the reference", assigned_to: "paper_agent", status: "done"}
    - {round: 5, action: "Rename §5.5 to 'Cross-Family Exploratory Analysis'", assigned_to: "paper_agent", status: "done"}
  resolution: "D138: §5.5 renamed. Adequate caveats present. Minor residual: MAE CI for cross-family pool not reported."
  resolution_round: null

- id: "R3-W12"
  summary: "STEM domains identical γ=+0.50 — prior sensitivity analysis addresses prior dominance"
  category: method
  severity: warning
  status: resolved
  first_raised_round: 3
  last_seen_round: 5
  mentions:
    - {round: 3, reviewers: "R2,R1", note: "Three domains identical γ=+0.50. Prior N(0,1) dominance?"}
    - {round: 4, reviewers: "R1,R2", note: "γ~N(0,1) covers ±2 logit units. No prior sensitivity analysis. Need at least N(0,0.5) and N(0,2) alternatives. Also need e_ij distribution."}
    - {round: 5, reviewers: "", note: "Not re-raised in R5. Prior sensitivity now in Appendix C: pooled prior-dominated (2.6×), Social Sciences data-dominated (1.2×). Resolved."}
  action_items:
    - {round: 3, action: "Check prior dominance", assigned_to: "main_agent", status: "done"}
    - {round: 4, action: "Run prior sensitivity with N(0,0.5) and N(0,2); report e_ij distribution", assigned_to: "main_agent", status: "done"}
  resolution: "Full prior sensitivity complete. Pooled: 2.6× prior-dominated. Social Sciences: 1.2× data-dominated, P(γ<0)≥97.95% across all priors. e_ij distribution reported. Not re-raised in R6."
  resolution_round: 5

- id: "R4-W2"
  summary: "Min-K%++ directional reversal — causal explanation is unverified hypothesis"
  category: method
  severity: warning
  status: in_progress
  first_raised_round: 4
  last_seen_round: 6
  mentions:
    - {round: 4, reviewers: "R1,R2", note: "§5.2 hypothesizes token-level surprisal disruption at 0.5B but provides no direct evidence. Alternative explanations not ruled out."}
    - {round: 5, reviewers: "R1,R2", note: "R1 W4: Min-K%++ reversal may be SFT artifact. R2 partial REBUT: paper already qualifies as post-hoc. Both AGREE: Conclusion claim must be scoped to 'under SFT injection'."}
